    .{ .slug = "console-time", .title = "console.time and console.timeEnd", .search = "console.time and console.timeEnd console-time console.time,console.timeEnd,window.console", .description = "Functions for measuring performance", .notes = "console.time() starts a timer you can use to track how long an operation takes. You give each timer a unique name, and may have up to 10,000 timers running on a given page. When you call console.timeEnd() with the same name, the browser will output the time, in milliseconds, that elapsed since the timer was started. These functions are not always available in workers. For example, in Firefox, they are available from version 38. More on using the console on mobile devices, see here.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–154: Full.", "Version history: 2–9: No; 10–156: Full.", "Version history: 3.1–3.2: No; 4–27: Full.", "Version history: 12–152: Full." } },
