    .{ .slug = "css-color-function", .title = "CSS color() function", .search = "CSS color() function css-color-function color(),Display-P3,A98-RGB,ProPhoto-RGB,REC-2020,Device-Dependent Colors,Profiled Colors,@color-profile,color space", .description = "The CSS color() function allows the browser to display colors in any color space, such as the P3 color space which can display colors outside of the default sRGB color space.", .notes = "For this function to work properly, the device screen and OS also needs to support the color space being used.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–107: No; 108–110: Disabled by default (#2); 111–154: Full.\n#2: Available behind the Experimental Web Platform features flag", "Version history: 2–110: No; 111–112: Disabled by default (#3); 113–156: Full.\n#3: Can be enabled by setting about:config flag layout.css.more_color_4.enabled to true", "Version history: 3.1–10: No; 10.1–14.1: Partial (#1); 15–27: Full.\n#1: Only supports display-p3 predefined color profile.", "Version history: 12–107: No; 108–110: Disabled by default (#2); 111–152: Full.\n#2: Available behind the Experimental Web Platform features flag" } },
