    .{ .slug = "flexbox", .title = "CSS Flexible Box Layout Module", .search = "CSS Flexible Box Layout Module flexbox flex-box,displayflex,flex-direction,flex-wrap,flex-flow,flex-grow,flex-shrink,flex-basis,display:flex,justify-content:space-between,justify-content:space-around,align-content:space-between,align-content:space-around,space-between", .description = "Method of positioning elements in horizontal or vertical stacks. Support includes all properties prefixed with flex, as well as display: flex, display: inline-flex, align-content, align-items, align-self, justify-content and order.", .notes = "Most partial support refers to supporting an older version of the specification or an older syntax.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–20: Partial (prefix required, #1); 21–28: Full (prefix required); 29–154: Full.\n#1: Only supports the old flexbox specification and does not support wrapping.", "Version history: 2–21: Partial (prefix required, #1); 22–27: Partial (#3); 28–156: Full.\n#1: Only supports the old flexbox specification and does not support wrapping.\n#3: Does not support flex-wrap, flex-flow or align-content properties", "Version history: 3.1–6: Partial (prefix required, #1); 6.1–8: Full (prefix required); 9–27: Full.\n#1: Only supports the old flexbox specification and does not support wrapping.", "Version history: 12–152: Full." } },
    .{ .slug = "font-loading", .title = "CSS Font Loading", .search = "CSS Font Loading font-loading fontface,fontfaceset,fontfacesource,document.fonts", .description = "This CSS module defines a scripting interface to font faces in CSS, allowing font faces to be easily created and loaded from script. It also provides methods to track the loading status of an individual font, or of all the fonts on an entire page.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–34: No; 35–154: Full.", "Version history: 2–34: No; 35–40: Disabled by default (#1); 41–156: Full.\n#1: Can be enabled in Firefox using the layout.css.font-loading-api.enabled flag. Enabled by default in Firefox 41. See this bug", "Version history: 3.1–9.1: No; 10–27: Full.", "Version history: 12–18: No; 79–152: Full." } },
    .{ .slug = "css-font-rendering-controls", .title = "CSS font-display", .search = "CSS font-display css-font-rendering-controls swap,fallback,optional,block,font-display", .description = "@font-face descriptor font-display that allows control over how a downloadable font renders before it is fully loaded.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–48: No; 49–59: Disabled by default; 60–154: Full.", "Version history: 2–45: No; 46–57: Disabled by default (#1); 58–156: Full.\n#1: Can be enabled via the layout.css.font-display.enabled flag", "Version history: 3.1–11: No; 11.1–27: Full.", "Version history: 12–18: No; 79–152: Full." } },
    .{ .slug = "font-feature", .title = "CSS font-feature-settings", .search = "CSS font-feature-settings font-feature font-feature,font-feature-settings,kern,kerning,font-variant-alternates,ligatures,font-variant-ligatures", .description = "Method of applying advanced typographic and language-specific font features to supported OpenType fonts.", .notes = "Whenever possible, font-variant shorthand property or an associated longhand property, font-variant-ligatures, font-variant-caps, font-variant-east-asian, font-variant-alternates, font-variant-numeric or font-variant-position should be used. This property is a low-level feature designed to handle special cases where no other way to enable or access an OpenType font feature exists. In particular, this CSS property shouldn't be used to enable small caps.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–15: No; 16–20: Partial (prefix required, #2); 21–47: Full (prefix required); 48–154: Full.\n#2: Partial support in older Chrome versions refers to lacking support in Mac OS X.", "Version history: 2–3.6: No; 4–14: Partial (prefix required, #1); 15–33: Full (prefix required); 34–156: Full.\n#1: From Gecko 2.0 (Firefox 4.0) to Gecko 14.0 (Firefox 14.0) included, Gecko supported an older syntax, slightly different from the modern one: https://hacks.mozilla.org/2010/11/firefox-4-font-feature-support/", "Version history: 3.1–3.2: No; 4–6: Partial; 6.1–9: No; 9.1–27: Full.", "Version history: 12–152: Full." } },
