    .{ .slug = "font-size-adjust", .title = "CSS font-size-adjust", .search = "CSS font-size-adjust font-size-adjust", .description = "Method of adjusting the font size in a matter that relates to the height of lowercase vs. uppercase letters. This makes it easier to set the size of fallback fonts.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–42: No; 43–119: Disabled by default (#1, #2, #3); 120–126: Disabled by default (#1); 127–154: Full.\n#1: Enabled through the \"experimental Web Platform features\" flag in chrome://flags\n#2: Missing support for two-value syntax. Issue for Chromium.\n#3: Missing support for from-font value. Issue for Chromium.", "Version history: 2: No; 3–91: Partial (#2, #3); 92–117: Partial (#3); 118–156: Full.\n#2: Missing support for two-value syntax. Issue for Chromium.\n#3: Missing support for from-font value. Issue for Chromium.", "Version history: 3.1–16.3: No; 16.4–16.6: Partial (#2, #3); 17.0–27: Full.\n#2: Missing support for two-value syntax. Issue for Chromium.\n#3: Missing support for from-font value. Issue for Chromium.", "Version history: 12–18: No; 79–116: Disabled by default (#1, #2, #3); 117–126: Disabled by default (#1); 127–152: Full.\n#1: Enabled through the \"experimental Web Platform features\" flag in chrome://flags\n#2: Missing support for two-value syntax. Issue for Chromium.\n#3: Missing support for from-font value. Issue for Chromium." } },
    .{ .slug = "font-smooth", .title = "CSS font-smooth", .search = "CSS font-smooth font-smooth font smooth,font smoothing,-webkit-font-smoothing,-moz-osx-font-smoothing", .description = "Controls the application of anti-aliasing when fonts are rendered.", .notes = "Though present in early (2002) drafts of CSS3 Fonts, font-smooth has been removed from this specification and is currently not on the standard track.", .summary = .{ "154 Partial (prefix required, #1, #3)", "156 Partial (prefix required, #2, #3, #4)", "27 Partial (prefix required, #1, #3)", "152 Partial (prefix required, #1, #3)" }, .details = .{ "Version history: 4: No; 5–154: Partial (prefix required, #1, #3).\n#1: WebKit implements something similar with a different name -webkit-font-smoothing and different values: none, antialiased and subpixel-antialiased.\n#3: Works only on Mac OS X platform.", "Version history: 2–24: No; 25–127: Partial (prefix required, #2, #3); 128–156: Partial (prefix required, #2, #3, #4).\n#2: Firefox implements something similar with a different name -moz-osx-font-smoothing and different values: auto, inherit, unset, grayscale.\n#3: Works only on Mac OS X platform.\n#4: Firefox 128 and later supports -webkit-font-smoothing: antialiased (by mapping to -moz-osx-font-smoothing: grayscale)", "Version history: 3.1–3.2: No; 4–27: Partial (prefix required, #1, #3).\n#1: WebKit implements something similar with a different name -webkit-font-smoothing and different values: none, antialiased and subpixel-antialiased.\n#3: Works only on Mac OS X platform.", "Version history: 12–18: No; 79–152: Partial (prefix required, #1, #3).\n#1: WebKit implements something similar with a different name -webkit-font-smoothing and different values: none, antialiased and subpixel-antialiased.\n#3: Works only on Mac OS X platform." } },
    .{ .slug = "css-font-stretch", .title = "CSS font-stretch", .search = "CSS font-stretch css-font-stretch font stretch", .description = "If a font has multiple types of variations based on the width of characters, this property allows the appropriate one to be selected. The property in itself does not cause the browser to stretch to a font. Note that font-stretch is an alias of the font-width CSS property.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–47: No; 48–154: Full.", "Version history: 2–8: No; 9–156: Full.", "Version history: 3.1–10.1: No; 11–27: Full.", "Version history: 12–152: Full." } },
