    .{ .slug = "css3-cursors-grab", .title = "CSS grab & grabbing cursors", .search = "CSS grab & grabbing cursors css3-cursors-grab", .description = "Support for the grab & grabbing values for the cursor property. Used to indicate that something can be grabbed (dragged to be moved).", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–67: Full (prefix required); 68–154: Full.", "Version history: 2–26: Full (prefix required); 27–156: Full.", "Version history: 3.1–10.1: Full (prefix required); 11–27: Full.", "Version history: 12–14: No; 15–152: Full." } },
    .{ .slug = "css-gradients", .title = "CSS Gradients", .search = "CSS Gradients css-gradients linear,linear-gradient,gradiant", .description = "Method of defining a linear or radial color gradient as a CSS image.", .notes = "Syntax used by browsers with prefixed support may be incompatible with that for proper support. Support can be somewhat emulated in older IE versions using the non-standard \"gradient\" filter. Firefox 10+, Opera 11.6+, Chrome 26+ and IE10+ also support the new \"to (side)\" syntax.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–9: Partial (prefix required, #3); 10–25: Full (prefix required); 26–154: Full.\n#3: Implements an earlier prefixed syntax as -webkit-gradient", "Version history: 2–3.5: No; 3.6–15: Partial (prefix required, #2); 16–35: Partial (#2); 36–156: Full.\n#2: Partial support in Safari and Older Firefox versions refers to not using premultiplied colors which results in unexpected behavior when using the transparent keyword as advised by the spec.", "Version history: 3.1–3.2: No; 4–5: Partial (prefix required, #2, #3); 5.1–6: Partial (prefix required, #2); 6.1–15.2-15.3: Partial (#2); 15.4–27: Full.\n#2: Partial support in Safari and Older Firefox versions refers to not using premultiplied colors which results in unexpected behavior when using the transparent keyword as advised by the spec.\n#3: Implements an earlier prefixed syntax as -webkit-gradient", "Version history: 12–152: Full." } },
    .{ .slug = "css-grid-lanes", .title = "CSS Grid Lanes", .search = "CSS Grid Lanes css-grid-lanes display:grid-lanes,grid,grid-row,grid-column,display:grid,masonry,waterfall,grid-template-columns:masonry,grid-template-rows:masonry,display:masonry", .description = "CSS Grid Lanes extends CSS Grid to create layouts with columns *or* rows (not both), allowing mixed aspect ratio content to pack neatly (also known as \"masonry\" or \"waterfall\" layout).", .notes = "", .summary = .{ "154 Disabled by default (#1)", "156 Disabled by default (#1)", "27 Full", "152 Disabled by default (#1)" }, .details = .{ "Version history: 4–139: No; 140–154: Disabled by default (#1).\n#1: An earlier version of the spec available behind a flag.", "Version history: 2–76: No; 77–156: Disabled by default (#1).\n#1: An earlier version of the spec available behind a flag.", "Version history: 3.1–16.3: No; 16.4–26.3: Disabled by default (#1); 26.4–27: Full.\n#1: An earlier version of the spec available behind a flag.", "Version history: 12–139: No; 140–152: Disabled by default (#1).\n#1: An earlier version of the spec available behind a flag." } },
    .{ .slug = "css-grid", .title = "CSS Grid Layout (level 1)", .search = "CSS Grid Layout (level 1) css-grid grids,grid-row,grid-column,grid-template,display:grid,displaygrid,inline-grid,fr unit,fractional unit,cssgrid,justify-content:space-between,justify-content:space-around,align-content:space-between,align-content:space-around,space-between", .description = "Method of using a grid concept to lay out content, providing a mechanism for authors to divide available space for layout into columns and rows using a set of predictable sizing behaviors. Includes support for all grid-* properties and the fr unit.", .notes = "See also support for subgrids", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–24: No; 25–28: No (polyfill available); 29–56: Disabled by default (#1); 57: Full (#4); 58–154: Full.\n#1: Enabled in Chrome through the \"experimental Web Platform features\" flag in chrome://flags\n#4: There are some bugs with overflow (1356820, 1348857, 1350925)", "Version history: 2–18: No; 19–39: No (polyfill available); 40–51: Disabled by default (#3); 52–53: Full (#4); 54–156: Full.\n#3: Enabled in Firefox through the layout.css.grid.enabled flag\n#4: There are some bugs with overflow (1356820, 1348857, 1350925)", "Version history: 3.1–5.1: No; 6–10: No (polyfill available); 10.1–27: Full.", "Version history: 12–15: Partial (prefix required, #2); 16–152: Full.\n#2: Partial support in IE refers to supporting an older version of the specification." } },
