    .{ .slug = "css-hyphens", .title = "CSS Hyphenation", .search = "CSS Hyphenation css-hyphens hyphen,shy", .description = "Method of controlling when words at the end of lines should be hyphenated using the \"hyphens\" property.", .notes = "Chrome < 55 and Android 4.0 Browser support \"-webkit-hyphens: none\", but not the \"auto\" property. It is advisable to set the @lang attribute on the HTML element to enable hyphenation support and improve accessibility.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–54: No; 55–87: Partial (#1); 88–154: Full.\n#1: Only supported on Android & Mac platforms (and only the \"auto\" value) for now. See commit & related bug.", "Version history: 2–5: No; 6–42: Full (prefix required); 43–156: Full.", "Version history: 3.1–5: No; 5.1–16.6: Full (prefix required); 17.0–27: Full.", "Version history: 12–18: Full (prefix required); 79–87: Partial (#1); 88–104: Partial (#2); 105–152: Full.\n#1: Only supported on Android & Mac platforms (and only the \"auto\" value) for now. See commit & related bug.\n#2: Only supported on Android & Mac platforms" } },
    .{ .slug = "css-if", .title = "CSS if() function", .search = "CSS if() function css-if condition,media,supports,style", .description = "The if() CSS function allows different values to be set for a property depending on the result of a conditional test. The test can be based on a style query, a media query, or a feature query.", .notes = "", .summary = .{ "154 Full", "156 No", "27 No", "152 Full" }, .details = .{ "Version history: 4–136: No; 137–154: Full.", "Version history: 2–156: No.", "Version history: 3.1–27: No.", "Version history: 12–136: No; 137–152: Full." } },
