    .{ .slug = "css-initial-letter", .title = "CSS Initial Letter", .search = "CSS Initial Letter css-initial-letter initial-letter,initial letter,letter,drop cap,dropcap,initial letters,letters", .description = "Method of creating an enlarged cap, including a drop or raised cap, in a robust way.", .notes = "", .summary = .{ "154 Partial (#2)", "156 No", "27 Partial (prefix required, #2)", "152 Partial (#2)" }, .details = .{ "Version history: 4–109: No; 110–154: Partial (#2).\n#2: Only supports the initial-letter property (not initial-letter-align or initial-letter-wrap).", "Version history: 2–156: No.", "Version history: 3.1–8: No; 9: Partial (#2); 9.1–18.3: Partial (prefix required, #1, #2); 18.4–27: Partial (prefix required, #2).\n#1: Web fonts have no affect on the initial letter. Instead a fallback system font is used.\n#2: Only supports the initial-letter property (not initial-letter-align or initial-letter-wrap).", "Version history: 12–109: No; 110–152: Partial (#2).\n#2: Only supports the initial-letter property (not initial-letter-align or initial-letter-wrap)." } },
