    .{ .slug = "justify-content-space-evenly", .title = "CSS justify-content: space-evenly", .search = "CSS justify-content: space-evenly justify-content-space-evenly", .description = "The \"space-evenly\" value for the justify-content property distributes the space between items evenly. It is similar to space-around but provides equal instead of half-sized space on the edges. Can be used in both CSS flexbox & grid.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–56: No; 57–59: Partial (#1); 60–154: Full.\n#1: Supported in CSS Grid, but not Flexbox", "Version history: 2–51: No; 52–156: Full.", "Version history: 3.1–10: No; 10.1: Partial (#1); 11–27: Full.\n#1: Supported in CSS Grid, but not Flexbox", "Version history: 12–15: No; 16–18: Partial (#1); 79–152: Full.\n#1: Supported in CSS Grid, but not Flexbox" } },
    .{ .slug = "css-line-clamp", .title = "CSS line-clamp", .search = "CSS line-clamp css-line-clamp", .description = "CSS property that will contain text to a given amount of lines when used in combination with display: -webkit-box. It will end with ellipsis when text-overflow: ellipsis is included.", .notes = "Older (presto-based) versions of the Opera browser have also supported the same effect using the proprietary -o-ellipsis-lastline; value for text-overflow.", .summary = .{ "154 Full (prefix required)", "156 Full (prefix required)", "27 Full (prefix required)", "152 Full (prefix required)" }, .details = .{ "Version history: 4–13: Unknown; 14–154: Full (prefix required).", "Version history: 2–67: No; 68–156: Full (prefix required).", "Version history: 3.1–4: No; 5–27: Full (prefix required).", "Version history: 12–16: No; 17–18: Full (#1); 79–152: Full (prefix required).\n#1: Supported in MS Edge with -webkit- prefix only (not with -ms-)" } },
    .{ .slug = "css-logical-props", .title = "CSS Logical Properties", .search = "CSS Logical Properties css-logical-props block-size,border-block,border-block-color,border-block-end,border-block-end-color,border-block-end-style,border-block-end-width,border-block-start,border-block-start-color,border-block-start-style,border-block-start-width,border-block-style,border-block-width,border-end-end-radius,border-end-start-radius,border-inline,border-inline-color,border-inline-end,border-inline-end-color,border-inline-end-style,border-inline-end-width,border-inline-start,border-inline-start-color,border-inline-start-style,border-inline-start-width,border-inline-style,border-inline-width,border-start-end-radius,border-start-start-radius,inline-size,inset,inset-block,inset-block-end,inset-block-start,inset-inline,inset-inline-end,inset-inline-start,margin-block,margin-block-end,margin-block-start,margin-inline,margin-inline-end,margin-inline-start,max-block-size,max-inline-size,min-block-size,min-inline-size,padding-block,padding-block-end,padding-block-start,padding-inline,padding-inline-end,padding-inline-start,recto,verso", .description = "Logical properties and values provide control of layout through logical, rather than physical, direction and dimension mappings. These properties are writing-mode relative equivalents of their corresponding physical properties.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–68: Partial (prefix required, #2); 69–86: Partial (#3, #4); 87–88: Partial (#4); 89–154: Full.\n#2: Like #1 but also supports *-before and *-end for *-block-start and *-block-end properties as well as start and end values for text-align.\n#3: Does not support the margin-block, margin-inline, padding-block, padding-inline, or any of the inset shorthand properties. Supported in newer Chromium browsers behind the #enable-experimental-web-platform-features flag.\n#4: Does not support the border-start-start-radius, border-start-end-radius, border-end-start-radius and border-end-end-radius property.", "Version history: 2: No; 3–40: Partial (prefix required, #1); 41–65: Partial (#3, #4); 66–156: Full.\n#1: Only supports the *-start, and *-end values for margin, border and padding, not the inline/block type values as defined in the spec.\n#3: Does not support the margin-block, margin-inline, padding-block, padding-inline, or any of the inset shorthand properties. Supported in newer Chromium browsers behind the #enable-experimental-web-platform-features flag.\n#4: Does not support the border-start-start-radius, border-start-end-radius, border-end-start-radius and border-end-end-radius property.", "Version history: 3.1–12: Partial (prefix required, #2); 12.1–14: Partial (#3, #4); 14.1: Partial (#4, #5); 15–27: Full.\n#2: Like #1 but also supports *-before and *-end for *-block-start and *-block-end properties as well as start and end values for text-align.\n#3: Does not support the margin-block, margin-inline, padding-block, padding-inline, or any of the inset shorthand properties. Supported in newer Chromium browsers behind the #enable-experimental-web-platform-features flag.\n#4: Does not support the border-start-start-radius, border-start-end-radius, border-end-start-radius and border-end-end-radius property.\n#5: Does not support the margin-block, margin-inline, padding-block, padding-inline shorthand properties when value is a CSS property. Supported when using a length value.", "Version history: 12–18: No; 79–86: Partial (#3, #4); 87–88: Partial (#4); 89–152: Full.\n#3: Does not support the margin-block, margin-inline, padding-block, padding-inline, or any of the inset shorthand properties. Supported in newer Chromium browsers behind the #enable-experimental-web-platform-features flag.\n#4: Does not support the border-start-start-radius, border-start-end-radius, border-end-start-radius and border-end-end-radius property." } },
    .{ .slug = "css-masks", .title = "CSS Masks", .search = "CSS Masks css-masks clip,clip-path,clip-rule,mask,mask-border,mask-clip,mask-image,mask-mode,mask-type,css masking", .description = "Method of displaying part of an element, using a selected image as a mask", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–119: Partial (prefix required, #1); 120–154: Full.\n#1: Partial support in WebKit/Blink browsers refers to supporting the mask-image and mask-box-image properties, but lacking support for other parts of the spec.", "Version history: 2–3: No; 3.5–52: Partial (#2); 53–156: Full.\n#2: Partial support in Firefox refers to only support for inline SVG mask elements i.e. mask: url(#foo).", "Version history: 3.1–3.2: No; 4–15.2-15.3: Partial (prefix required, #1); 15.4–27: Full.\n#1: Partial support in WebKit/Blink browsers refers to supporting the mask-image and mask-box-image properties, but lacking support for other parts of the spec.", "Version history: 12–16: No; 17: Disabled by default (#4, #5); 18: Partial (#6, #7); 79–119: Partial (prefix required, #1); 120–152: Full.\n#1: Partial support in WebKit/Blink browsers refers to supporting the mask-image and mask-box-image properties, but lacking support for other parts of the spec.\n#4: Can be enabled in MS edge behind the \"Enable CSS Masking\" flag.\n#5: Partial support refers to supporting mask-image and mask-size\n#6: Partial support refers to supporting mask-image, mask-size, mask-position, mask-repeat and mask-composite\n#7: Edge also recognizes and supports all the -webkit- prefixed equivalents of the unprefixed properties for site compatibility" } },
    .{ .slug = "css-math-functions", .title = "CSS math functions min(), max() and clamp()", .search = "CSS math functions min(), max() and clamp() css-math-functions min,min(),max,max(),clamp,clamp()", .description = "More advanced mathematical expressions in addition to calc()", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–78: No; 79–154: Full.", "Version history: 2–74: No; 75–156: Full.", "Version history: 3.1–11: No; 11.1–13: Partial (#1); 13.1–27: Full.\n#1: Safari did not support clamp()", "Version history: 12–18: No; 79–152: Full." } },
    .{ .slug = "minmaxwh", .title = "CSS min/max-width/height", .search = "CSS min/max-width/height minmaxwh min-width,min-height,max-width,max-height", .description = "Method of setting a minimum or maximum width or height to an element.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–154: Full.", "Version history: 2–156: Full.", "Version history: 3.1–27: Full.", "Version history: 12–152: Full." } },
    .{ .slug = "css-motion-paths", .title = "CSS Motion Path", .search = "CSS Motion Path css-motion-paths offset-position,offset-distance,offset-rotate", .description = "Allows elements to be animated along SVG paths or shapes via the offset-path property. Originally defined as the motion-path property.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–42: No; 43–45: Disabled by default (#1); 46–154: Full.\n#1: Requires the \"Experimental Web Platform features\" flag to be enabled", "Version history: 2–71: No; 72–156: Full.", "Version history: 3.1–15.6: No; 16.0–27: Full.", "Version history: 12–18: No; 79–152: Full." } },
    .{ .slug = "css-namespaces", .title = "CSS namespaces", .search = "CSS namespaces css-namespaces", .description = "Using the @namespace at-rule, elements of other namespaces (e.g. SVG) can be targeted using the pipe (|) selector.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–154: Full.", "Version history: 2–156: Full.", "Version history: 3.1–3.2: Unknown; 4–27: Full.", "Version history: 12–152: Full." } },
    .{ .slug = "css-nesting", .title = "CSS Nesting", .search = "CSS Nesting css-nesting &,@nest,nested css", .description = "CSS nesting provides the ability to nest one style rule inside another, with the selector of the child rule relative to the selector of the parent rule. Similar behavior previously required a CSS pre-processor.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–108: No; 109–111: Disabled by default (#1); 112–119: Partial (#3); 120–154: Full.\n#1: Available behind the Experimental Web Platform features flag\n#3: Does not allow nesting of type (element) selectors without starting with a symbol, like the & nesting selector. Chromium issue", "Version history: 2–114: No; 115–116: Disabled by default (#2); 117–156: Full.\n#2: Available behind the layout.css.nesting.enabled flag", "Version history: 3.1–16.4: No; 16.5–17.1: Partial (#3); 17.2–27: Full.\n#3: Does not allow nesting of type (element) selectors without starting with a symbol, like the & nesting selector. Chromium issue", "Version history: 12–108: No; 109–111: Disabled by default (#1); 112–119: Partial (#3); 120–152: Full.\n#1: Available behind the Experimental Web Platform features flag\n#3: Does not allow nesting of type (element) selectors without starting with a symbol, like the & nesting selector. Chromium issue" } },
    .{ .slug = "outline", .title = "CSS outline properties", .search = "CSS outline properties outline -moz-outline,outline-width,outline-style,outline-color,outline-radius", .description = "The CSS outline properties draw a border around an element that does not affect layout, making it ideal for highlighting. This covers the outline shorthand, as well as outline-width, outline-style, outline-color and outline-offset.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–154: Full.", "Version history: 2–156: Full.", "Version history: 3.1–27: Full.", "Version history: 12–14: Partial (#1, #2); 15–152: Full.\n#1: Also supports the value of invert for outline-color. (support of this value is optional for browsers)\n#2: Does not support outline-offset." } },
    .{ .slug = "css-overflow", .title = "CSS overflow property", .search = "CSS overflow property css-overflow overflow:hidden,overflow:scroll,overflow:clip", .description = "Originally a single property for controlling overflowing content in both horizontal & vertical directions, the overflow property is now a shorthand for overflow-x & overflow-y. The latest version of the specification also introduces the clip value that blocks programmatic scrolling.", .notes = "Effectively all browsers support the CSS 2.1 definition for single-value overflow as well as overflow-x & overflow-y and values visible, hidden, scroll & auto", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–67: Partial (#1, #2); 68–89: Partial (#2); 90–154: Full.\n#1: Does not support the two value overflow shorthand\n#2: Does not support the clip value", "Version history: 2–60: Partial (#1, #2); 61–80: Partial (#2); 81–156: Full.\n#1: Does not support the two value overflow shorthand\n#2: Does not support the clip value", "Version history: 3.1–13: Partial (#1, #2); 13.1–15.6: Partial (#2); 16.0–27: Full.\n#1: Does not support the two value overflow shorthand\n#2: Does not support the clip value", "Version history: 12–18: Partial (#1, #2); 79–89: Partial (#2); 90–152: Full.\n#1: Does not support the two value overflow shorthand\n#2: Does not support the clip value" } },
    .{ .slug = "css-overflow-anchor", .title = "CSS overflow-anchor (Scroll Anchoring)", .search = "CSS overflow-anchor (Scroll Anchoring) css-overflow-anchor overflow-anchor,scroll anchoring", .description = "Changes in DOM elements above the visible region of a scrolling box can result in the page moving while the user is in the middle of consuming the content. By default, the value of overflow-anchor is auto, it can mitigate this jarring user experience by keeping track of the position of an anchor node and adjusting the scroll offset accordingly", .notes = "", .summary = .{ "154 Full", "156 Full", "27 No", "152 Full" }, .details = .{ "Version history: 4–55: No; 56–154: Full.", "Version history: 2–65: No; 66–156: Full.", "Version history: 3.1–27: No.", "Version history: 12–18: No; 79–152: Full." } },
    .{ .slug = "css-overflow-overlay", .title = "CSS overflow: overlay", .search = "CSS overflow: overlay css-overflow-overlay", .description = "The overlay value of the overflow CSS property is a non-standard value to make scrollbars appear on top of content rather than take up space. This value is deprecated and related functionality being standardized as the scrollbar-gutter property.", .notes = "", .summary = .{ "154 No (#1)", "156 No", "27 No (#1)", "152 No (#1)" }, .details = .{ "Version history: 4–14: Unknown; 15–113: Full; 114–154: No (#1).\n#1: The overlay value is recognized, but behaves the same as \"auto\".", "Version history: 2–156: No.", "Version history: 3.1–3.2: Unknown; 4–11.1: Full; 12–27: No (#1).\n#1: The overlay value is recognized, but behaves the same as \"auto\".", "Version history: 12–18: No; 79–113: Full; 114–152: No (#1).\n#1: The overlay value is recognized, but behaves the same as \"auto\"." } },
    .{ .slug = "css-overscroll-behavior", .title = "CSS overscroll-behavior", .search = "CSS overscroll-behavior css-overscroll-behavior scroll-boundary-behavior,overscroll-behavior-x,overscroll-behavior-y,-ms-scroll-chaining", .description = "CSS property to control the behavior when the scroll position of a scroll container reaches the edge of the scrollport.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–62: No; 63–64: Partial (#2); 65–154: Full.\n#2: Does not support overscroll-behavior: none; on the body element to prevent the overscroll glow and rubberbanding effects.", "Version history: 2–58: No; 59–156: Full.", "Version history: 3.1–14: No; 14.1–15.6: Disabled by default (#4); 16.0–27: Full.\n#4: Can be enabled in the \"Experimental Features\" developer menu", "Version history: 12–17: Partial (#1); 18: Partial (#3); 79–152: Full.\n#1: Supports the precursor version of the property: -ms-scroll-chaining, which works similarly. IE support is limited to Windows 8 & above\n#3: Incorrectly treats none as contain see MDN and Edge 18 changelog" } },
    .{ .slug = "css-page-break", .title = "CSS page-break properties", .search = "CSS page-break properties css-page-break page-break-before,page-break-after,page-break-inside,always,avoid", .description = "Properties to control the way elements are broken across (printed) pages.", .notes = "Not all mobile browsers offer print support; support listed for these is based on browser engine capability.", .summary = .{ "154 Full (#1, #3)", "156 Partial (#2, #3)", "27 Partial (#1, #2, #3)", "152 Full (#1, #3)" }, .details = .{ "Version history: 4–107: Partial (#1, #2, #3); 108–154: Full (#1, #3).\n#1: Supports the page-break-* alias from the CSS 2.1 specification, but not the break-* properties from the latest spec.\n#2: Partial support is due to not supporting avoid for page-break-before & page-break-after (only page-break-inside).\n#3: Treats the left and right values like always (as allowed by specification).", "Version history: 2–64: Partial (#1, #2, #3); 65–156: Partial (#2, #3).\n#1: Supports the page-break-* alias from the CSS 2.1 specification, but not the break-* properties from the latest spec.\n#2: Partial support is due to not supporting avoid for page-break-before & page-break-after (only page-break-inside).\n#3: Treats the left and right values like always (as allowed by specification).", "Version history: 3.1–9.1: Partial (#1, #2, #3); 10: Partial (#2, #3); 10.1–27: Partial (#1, #2, #3).\n#1: Supports the page-break-* alias from the CSS 2.1 specification, but not the break-* properties from the latest spec.\n#2: Partial support is due to not supporting avoid for page-break-before & page-break-after (only page-break-inside).\n#3: Treats the left and right values like always (as allowed by specification).", "Version history: 12–18: Partial (#1, #2); 79–107: Partial (#1, #2, #3); 108–152: Full (#1, #3).\n#1: Supports the page-break-* alias from the CSS 2.1 specification, but not the break-* properties from the latest spec.\n#2: Partial support is due to not supporting avoid for page-break-before & page-break-after (only page-break-inside).\n#3: Treats the left and right values like always (as allowed by specification)." } },
    .{ .slug = "css-paged-media", .title = "CSS Paged Media (@page)", .search = "CSS Paged Media (@page) css-paged-media", .description = "CSS at-rule (@page) to define page-specific rules when printing web pages, such as margin per page and page dimensions.", .notes = "Currently no browsers appear to support the marks & bleed properties from the latest version of the specification.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–14: Unknown; 15–154: Full.", "Version history: 2–18: No; 19–94: Partial (#1); 95–156: Full.\n#1: Does not support the size property", "Version history: 3.1–18.1: No; 18.2–27: Full.", "Version history: 12–18: Partial (#1); 79–152: Full.\n#1: Does not support the size property" } },
