    .{ .slug = "pointer-events", .title = "CSS pointer-events (for HTML)", .search = "CSS pointer-events (for HTML) pointer-events pointerevents,pointer-events:none", .description = "This CSS property, when set to \"none\" allows elements to not receive hover/click events, instead the event will occur on anything behind it.", .notes = "Already part of the SVG specification, and all SVG-supporting browsers appear to support the property on SVG elements.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–154: Full.", "Version history: 2–3.5: No; 3.6–156: Full.", "Version history: 3.1–3.2: No; 4–27: Full.", "Version history: 12–152: Full." } },
    .{ .slug = "css-fixed", .title = "CSS position:fixed", .search = "CSS position:fixed css-fixed", .description = "Method of keeping an element in a fixed location regardless of scroll position", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–154: Full.", "Version history: 2–156: Full.", "Version history: 3.1–9: Full; 9.1: Full (#4); 10–27: Full.\n#4: in Safari 9.1, having a position:fixed-element inside an animated element, may cause the position:fixed-element to not appear.", "Version history: 12–152: Full." } },
    .{ .slug = "css-sticky", .title = "CSS position:sticky", .search = "CSS position:sticky css-sticky", .description = "Keeps elements positioned as \"fixed\" or \"relative\" depending on how it appears in the viewport. As a result the element is \"stuck\" when necessary while scrolling.", .notes = "sticks to its nearest ancestor that has a scrolling mechanism (created when overflow is hidden, scroll, auto, or overlay), even if that ancestor isn't the nearest actually scrolling ancestor", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–22: No; 23–36: Disabled by default (#2); 37–51: No; 52–55: Disabled by default (#2); 56–90: Partial (#4); 91–154: Full.\n#2: Enabled through the \"experimental Web Platform features\" flag\n#4: Supported on th elements, but not thead or tr - See Chrome bug", "Version history: 2–25: No; 26–31: Disabled by default (#1); 32–58: Partial (#3); 59–156: Full.\n#1: Can be enabled in Firefox by setting the about:config preference layout.css.sticky.enabled to true\n#3: Not supported on any table parts - See Firefox bug", "Version history: 3.1–6: No; 6.1–7: Partial (prefix required, #5); 7.1–12.1: Full (prefix required); 13–27: Full.\n#5: Do not appear to support sticky table headers", "Version history: 12–15: No; 16–18: Partial (#6); 79–90: Partial (#4); 91–152: Full.\n#4: Supported on th elements, but not thead or tr - See Chrome bug\n#6: Supported on th elements, but not thead or tr - See Edge bug" } },
    .{ .slug = "css-color-adjust", .title = "CSS print-color-adjust", .search = "CSS print-color-adjust css-color-adjust color-adjust,print-color-adjust,color adjust,print color adjust,coloradjust,printcoloradjust", .description = "The print-color-adjust (or -webkit-print-color-adjust as prefixed in WebKit/Blink browsers) property is a CSS extension that can be used to force printing of background colors and images.", .notes = "", .summary = .{ "154 Full (prefix required)", "156 Full", "27 Full", "152 Full (prefix required)" }, .details = .{ "Version history: 4–18: Unknown; 19–154: Full (prefix required).", "Version history: 2–47: No; 48–156: Full.", "Version history: 3.1–5.1: No; 6–15.2-15.3: Full (prefix required); 15.4–27: Full.", "Version history: 12–18: No; 79–152: Full (prefix required)." } },
    .{ .slug = "css-reflections", .title = "CSS Reflections", .search = "CSS Reflections css-reflections box-reflect", .description = "Method of displaying a reflection of an element", .notes = "Similar effect can be achieved in Firefox 4+ using the -moz-element() background property", .summary = .{ "154 Full (prefix required)", "156 No", "27 Full (prefix required)", "152 Full (prefix required)" }, .details = .{ "Version history: 4–154: Full (prefix required).", "Version history: 2–156: No.", "Version history: 3.1–3.2: No; 4–27: Full (prefix required).", "Version history: 12–18: No; 79–152: Full (prefix required)." } },
    .{ .slug = "css-regions", .title = "CSS Regions", .search = "CSS Regions css-regions", .description = "Method of flowing content into multiple elements, allowing magazine-like layouts. While once supported in WebKit-based browsers and Internet Explorer, implementing the feature is no longer being pursued by any browser.", .notes = "", .summary = .{ "154 No", "156 No", "27 No", "152 No" }, .details = .{ "Version history: 4–14: No; 15–18: Partial (prefix required); 19–34: Disabled by default; 35–154: No.", "Version history: 2–156: No.", "Version history: 3.1–6: No; 6.1–11: Full (prefix required); 11.1–27: No.", "Version history: 12–18: Partial (prefix required, #1, #2); 79–152: No.\n#1: Support is limited to using an iframe as a content source with the -ms-flow-into: flow_name; and -ms-flow-from: flow_name; syntax.\n#2: Partial support refers to not supporting the region-fragment property." } },
    .{ .slug = "css-relative-colors", .title = "CSS Relative color syntax", .search = "CSS Relative color syntax css-relative-colors", .description = "Relative color syntax in CSS allows a color to be defined relative to another color using the from keyword and optionally calc() for any of the color values.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–117: No; 118: Disabled by default (#1); 119–130: Partial (#2); 131–154: Full.\n#1: Can be enabled in Chrome via the #enable-experimental-web-platform-features flag in chrome://flags\n#2: Does not support currentcolor or system color keywords (Firefox bug 1893966)", "Version history: 2–127: No; 128–132: Partial (#2); 133–156: Full.\n#2: Does not support currentcolor or system color keywords (Firefox bug 1893966)", "Version history: 3.1–16.3: No; 16.4–17.6: Partial (#2); 18.0–27: Full.\n#2: Does not support currentcolor or system color keywords (Firefox bug 1893966)", "Version history: 12–117: No; 118: Disabled by default (#1); 119–130: Partial (#2); 131–152: Full.\n#1: Can be enabled in Chrome via the #enable-experimental-web-platform-features flag in chrome://flags\n#2: Does not support currentcolor or system color keywords (Firefox bug 1893966)" } },
