    .{ .slug = "font-kerning", .title = "CSS3 font-kerning", .search = "CSS3 font-kerning font-kerning", .description = "Controls the usage of the kerning information (spacing between letters) stored in the font. Note that this only affects OpenType fonts with kerning information, it has no effect on other fonts.", .notes = "Browsers with support for font feature settings can also set kerning value.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–28: No; 29–32: Full (prefix required); 33–154: Full.", "Version history: 2–23: No; 24–33: Disabled by default (#1); 34–156: Full.\n#1: Disabled by default, can be enabled using preference layout.css.font-features.enabled - defaulting to true on Nightly and Aurora only.", "Version history: 3.1–6.1: No; 7–9: Full (prefix required); 9.1–27: Full.", "Version history: 12–18: No; 79–152: Full." } },
    .{ .slug = "css-image-orientation", .title = "CSS3 image-orientation", .search = "CSS3 image-orientation css-image-orientation image-orientation,from-image,flip", .description = "CSS property used generally to fix the intended orientation of an image. This can be done using 90 degree increments or based on the image's EXIF data using the \"from-image\" value.", .notes = "Opening the image in a new tab in Chrome results in the image shown in the orientation according to the EXIF data.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–80: No; 81–88: Full (#2); 89–154: Full.\n#2: Has a bug where the browser is not maintaining the image’s aspect ratio when object-fit: cover and image-orientation: from-image are used together.", "Version history: 2–25: No; 26–156: Full.", "Version history: 3.1–13: No; 13.1–27: Full.", "Version history: 12–80: No; 81–88: Full (#2); 89–152: Full.\n#2: Has a bug where the browser is not maintaining the image’s aspect ratio when object-fit: cover and image-orientation: from-image are used together." } },
