    .{ .slug = "registerprotocolhandler", .title = "Custom protocol handling", .search = "Custom protocol handling registerprotocolhandler", .description = "Method of allowing a webpage to handle a given protocol using navigator.registerProtocolHandler. This allows certain URLs to be opened by a given web application, for example mailto: addresses can be opened by a webmail client.", .notes = "", .summary = .{ "154 Full (#1)", "156 Full", "27 No", "152 Full (#1)" }, .details = .{ "Version history: 4–12: No; 13–154: Full (#1).\n#1: Supports protocols mailto, mms, nntp, rtsp, and webcal but requires custom protocols to start with web+", "Version history: 2: No; 3–156: Full.", "Version history: 3.1–27: No.", "Version history: 12–18: No; 79–152: Full (#1).\n#1: Supports protocols mailto, mms, nntp, rtsp, and webcal but requires custom protocols to start with web+" } },
    .{ .slug = "customevent", .title = "CustomEvent", .search = "CustomEvent customevent custom events,custom,event", .description = "A DOM event interface that can carry custom application-defined data.", .notes = "Not supported in some versions of Android's old WebKit-based WebView.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4: No; 5–8: Unknown; 9–12: Partial (#1, #2); 13–14: Unknown; 15–154: Full.\n#1: While a window.CustomEvent object exists, it cannot be called as a constructor. Instead of new CustomEvent(...), you must use e = document.createEvent('CustomEvent') and then e.initCustomEvent(...)\n#2: There is no window.CustomEvent object, but document.createEvent('CustomEvent') still works.", "Version history: 2–5: No; 6–10: Partial (#1); 11–156: Full.\n#1: While a window.CustomEvent object exists, it cannot be called as a constructor. Instead of new CustomEvent(...), you must use e = document.createEvent('CustomEvent') and then e.initCustomEvent(...)", "Version history: 3.1–4: No; 5: Unknown; 5.1: Partial (#1, #2); 6: Unknown; 6.1–27: Full.\n#1: While a window.CustomEvent object exists, it cannot be called as a constructor. Instead of new CustomEvent(...), you must use e = document.createEvent('CustomEvent') and then e.initCustomEvent(...)\n#2: There is no window.CustomEvent object, but document.createEvent('CustomEvent') still works.", "Version history: 12–152: Full." } },
