    .{ .slug = "datauri", .title = "Data URIs", .search = "Data URIs datauri data url,datauris,data uri,dataurl,dataurls,base64", .description = "Method of embedding images and other files in webpages as a string of text, generally using base64 encoding.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–154: Full.", "Version history: 2–156: Full.", "Version history: 3.1–27: Full.", "Version history: 12–13: Partial (#2); 14: Partial (#2, #3); 15–18: Partial (#2); 79–152: Full.\n#2: Support is limited to images and linked resources like CSS or JS, not HTML files. Maximum size limit is 4GB.\n#3: SVGs with XML declarations are not displayed when used in data-urls" } },
    .{ .slug = "datalist", .title = "Datalist element", .search = "Datalist element datalist list attribute,input", .description = "Method of setting a list of options for a user to select in a text field, while leaving the ability to enter a custom value.", .notes = "While most commonly used on text fields, datalists can also be used on other input types. IE11 supports the element on range fields. Chrome and Opera also support datalists to suggest given values on range, color and date/time fields.", .summary = .{ "154 Full", "156 Partial (#7)", "27 Full", "152 Full" }, .details = .{ "Version history: 4–19: No (polyfill available); 20–68: Partial (#1); 69–154: Full.\n#1: Partial support refers to a bug where long lists of items are unscrollable resulting in unselectable options.", "Version history: 2–3.6: No (polyfill available); 4–101: Partial (#3, #6); 102–109: Partial (#3); 110–156: Partial (#7).\n#3: Partial support refers to no support for datalists on non-text fields (e.g. number, range, color, date and time).\n#6: In Firefox, autocomplete must be set to off to make dynamic datalist work due to a bug\n#7: Partial support refers to no support for datalists on date and time fields.", "Version history: 3.1–12: No (polyfill available); 12.1–27: Full.", "Version history: 12–15: Partial (#2); 16–18: Partial (#2, #4); 79–152: Full.\n#2: Partial support in IE refers to significantly buggy behavior (IE11+ does send the input and change events upon selection).\n#4: Partial support in Edge refers to disappearing option elements on focusing the input element via tab." } },
