    .{ .slug = "dnssec", .title = "DNSSEC and DANE", .search = "DNSSEC and DANE dnssec DNS Security Extensions,Domain Name System Security Extensions,DNS based Authentication of Named Entities,TLSA", .description = "Method of validating a DNS response against a trusted root server. Mitigates various attacks that could reroute a user to a fake site while showing the real URL for the original site.", .notes = "Browsers have generally decided to not implement DNSSEC validation because the added complexity outweighs the improvements to the browser. DNSSEC is still useful as it is widely used to protect delivery of records between DNS servers, only failing to protect the delivery from the last DNS server to the browser. Certificate transparency is widely used and tries to provide the same security as DNSSEC but by very different means.", .summary = .{ "154 Partial (#1)", "156 Partial (#1)", "27 Partial (#1)", "152 Partial (#1)" }, .details = .{ "Version history: 4–5: Partial (#1); 6–30: Partial (#1, #2); 31–154: Partial (#1).\n#1: Does not support DNSSEC but still benefits greatly from it, as most of the security improvements are gained in the DNS-network and not in the browser.\n#2: Early versions of Chrome experimented with browser-level validation.", "Version history: 2–156: Partial (#1).\n#1: Does not support DNSSEC but still benefits greatly from it, as most of the security improvements are gained in the DNS-network and not in the browser.", "Version history: 3.1–27: Partial (#1).\n#1: Does not support DNSSEC but still benefits greatly from it, as most of the security improvements are gained in the DNS-network and not in the browser.", "Version history: 12–152: Partial (#1).\n#1: Does not support DNSSEC but still benefits greatly from it, as most of the security improvements are gained in the DNS-network and not in the browser." } },
