    .{ .slug = "focusin-focusout-events", .title = "focusin & focusout events", .search = "focusin & focusout events focusin-focusout-events focusin,focusout,focus,event", .description = "The focusin and focusout events fire just before the element gains or loses focus, and they bubble. By contrast, the focus and blur events fire after the focus has shifted, and don't bubble.", .notes = "In browsers that don't support these events, one alternative is to use a capture phase event listener for the focus and/or blur events.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–14: Unknown; 15–154: Full.", "Version history: 2–51: No; 52–156: Full.", "Version history: 3.1–5: Unknown; 5.1–27: Full.", "Version history: 12–152: Full." } },
    .{ .slug = "font-unicode-range", .title = "Font unicode-range subsetting", .search = "Font unicode-range subsetting font-unicode-range font face,unicode,unicode-range", .description = "This @font-face descriptor defines the set of Unicode codepoints that may be supported by the font face for which it is declared. The descriptor value is a comma-delimited list of Unicode range ( ) values. The union of these ranges defines the set of codepoints that serves as a hint for user agents when deciding whether or not to download a font resource for a given text run.", .notes = "Partial support indicates that unnecessary code-ranges are downloaded by the browser - see browser test matrix.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–35: Partial; 36–154: Full.", "Version history: 2–35: No; 36–43: Disabled by default (#1); 44–156: Full.\n#1: Can be enabled in Firefox using the layout.css.unicode-range.enabled flag", "Version history: 3.1–9.1: Partial; 10–27: Full.", "Version history: 12–16: Partial; 17–152: Full." } },
