    .{ .slug = "heif", .title = "HEIF/HEIC image format", .search = "HEIF/HEIC image format heif heic,hevc", .description = "A modern image format based on the HEVC video format. HEIC generally has better compression than WebP, JPEG, PNG and GIF. It is hard for browsers to support HEIC because it is complex and expensive to license. AVIF and JPEG XL provide free licenses and are designed to supersede HEIC.", .notes = "", .summary = .{ "154 No", "156 No", "27 Full", "152 No" }, .details = .{ "Version history: 4–154: No.", "Version history: 2–156: No.", "Version history: 3.1–10.1: No; 11–16.6: No (#1); 17.0–27: Full.\n#1: Was supported natively in macOS/iOS, but was not supported in Safari.", "Version history: 12–152: No." } },
    .{ .slug = "hevc", .title = "HEVC/H.265 video format", .search = "HEVC/H.265 video format hevc h265", .description = "The High Efficiency Video Coding (HEVC) compression standard is a video compression format intended to succeed H.264. It is hard for browsers to universally support HEVC because it is complex and expensive to license. HEVC competes with AV1 which has similar compression quality and provides a free license.", .notes = "", .summary = .{ "154 Partial (#5)", "156 Partial (#8)", "27 Full", "152 Partial (#4)" }, .details = .{ "Version history: 4–106: No; 107–154: Partial (#5).\n#5: Supported for all devices on macOS (>= Big Sur 11.0) and Android (>= 5.0), for devices with hardware support on Windows (>= Windows 8), and for devices with hardware support powered by VAAPI on Linux and ChromeOS", "Version history: 2–119: No; 120: No (#6); 121–136: Disabled by default (#7); 137–156: Partial (#8).\n#6: Supported for devices with hardware support (the range is the same as Edge) on Windows in Nightly only. 10-bit or higher colors are not supported.\n#7: Supported for devices with hardware support (the range is the same as Edge) on Windows only. Enabled by default in Nightly and can be enabled via the media.wmf.hevc.enabled pref in about:config. 10-bit or higher colors are not supported.\n#8: Supported for devices with hardware support, software fallback in some cases. See details here on MDN.", "Version history: 3.1–10.1: No; 11–12.1: Partial (#3); 13–27: Full.\n#3: Supported only on macOS High Sierra or later", "Version history: 12–18: Partial (#1); 79–152: Partial (#4).\n#1: Supported only for devices with hardware support\n#4: Supported for all devices on macOS (>= Big Sur 11.0) and Android (>= 5.0) if Edge >= 107, for devices with hardware support on Windows (>= Windows 10 1709) when HEVC video extensions from the Microsoft Store is installed" } },
    .{ .slug = "hidden", .title = "hidden attribute", .search = "hidden attribute hidden", .description = "The hidden attribute may be applied to any element, and effectively hides elements similar to display: none in CSS.", .notes = "The hidden state can be easily overridden with a CSS display property set to anything other than none.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–5: No; 6–154: Full.", "Version history: 2–3.6: No; 4–156: Full.", "Version history: 3.1–5: No; 5.1–27: Full.", "Version history: 12–152: Full." } },
    .{ .slug = "high-resolution-time", .title = "High Resolution Time API", .search = "High Resolution Time API high-resolution-time performance,now,testing", .description = "Method to provide the current time in sub-millisecond resolution and such that it is not subject to system clock skew or adjustments. Called using performance.now()", .notes = "The timestamp is not actually high-resolution. To mitigate security threats such as Spectre, browsers currently round the result to varying degrees.", .summary = .{ "154 Full", "156 Full (#2, #4)", "27 Full", "152 Full" }, .details = .{ "Version history: 4–19: No; 20–23: Full (prefix required); 24–154: Full.", "Version history: 2–14: No; 15–54: Full; 55–57: Full (#1); 58–59: Full (#2, #3); 60–156: Full (#2, #4).\n#1: In Firefox 55-57, the privacy.resistFingerprinting preference can be enabled to change the precision to 100ms.\n#2: In Firefox, the privacy.resistFingerprinting preference can be enabled to change the precision to 100ms or the value of privacy.resistFingerprinting.reduceTimerPrecision.microseconds, whichever is larger.\n#3: In Firefox 58-59, the privacy.reduceTimerPrecision preference is enabled by default and defaults to 20us.\n#4: In Firefox, the privacy.reduceTimerPrecision preference is enabled by default and defaults to 2ms.", "Version history: 3.1–7.1: No; 8–27: Full.", "Version history: 12–152: Full." } },
    .{ .slug = "kerning-pairs-ligatures", .title = "High-quality kerning pairs & ligatures", .search = "High-quality kerning pairs & ligatures kerning-pairs-ligatures optimizeLegibility,optimizeSpeed,geometricPrecision", .description = "When used in HTML, the unofficial text-rendering: optimizeLegibility CSS property enables high-quality kerning and ligatures in certain browsers. Newer browsers have this behavior enabled by default.", .notes = "The text-rendering property is specified in SVG, though behavior there is not related to kerning pairs & ligatures.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–154: Full.", "Version history: 2: No; 3–156: Full.", "Version history: 3.1–4: No; 5–27: Full.", "Version history: 12–17: No; 18–152: Full." } },
