    .{ .slug = "html5semantic", .title = "HTML5 semantic elements", .search = "HTML5 semantic elements html5semantic section,article,aside,header,footer,nav,figure,figcaption,time,mark,main, , , , , , , , , , ,", .description = "HTML5 offers some new elements, primarily for semantic purposes. The elements include: section, article, aside, header, footer, nav, figure, figcaption, time, mark & main.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–5: Partial (#1); 6–25: Partial (#2); 26–154: Full.\n#1: Partial support refers to missing the default styling, as technically the elements are considered \"unknown\". This is easily taken care of by manually setting the default display value for each tag.\n#2: Partial support refers to only the element (added later to the spec) being \"unknown\", though it can still be used and styled.", "Version history: 2: No; 3–3.6: Partial (#1); 4–20: Partial (#2); 21–156: Full.\n#1: Partial support refers to missing the default styling, as technically the elements are considered \"unknown\". This is easily taken care of by manually setting the default display value for each tag.\n#2: Partial support refers to only the element (added later to the spec) being \"unknown\", though it can still be used and styled.", "Version history: 3.1–4: Partial (#1); 5–6: Partial (#2); 6.1–27: Full.\n#1: Partial support refers to missing the default styling, as technically the elements are considered \"unknown\". This is easily taken care of by manually setting the default display value for each tag.\n#2: Partial support refers to only the element (added later to the spec) being \"unknown\", though it can still be used and styled.", "Version history: 12–152: Full." } },
    .{ .slug = "innertext", .title = "HTMLElement.innerText", .search = "HTMLElement.innerText innertext inner,text,content", .description = "A property representing the text within a DOM element and its descendants. As a getter, it approximates the text the user would get if they highlighted the contents of the element with the cursor and then copied to the clipboard.", .notes = "This test only checks that the property exists and works correctly in a very simple case. This blog post by kangax explains the history of this property, gives much more detailed cross-browser compatibility information, and gives a detailed strawman specification for the property. HTMLElement.innerText is similar to, but has some important differences from, the standard Node.textContent property.", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–154: Full.", "Version history: 2–44: No; 45–156: Full.", "Version history: 3.1: Unknown; 3.2–27: Full.", "Version history: 12–152: Full." } },
    .{ .slug = "http-live-streaming", .title = "HTTP Live Streaming (HLS)", .search = "HTTP Live Streaming (HLS) http-live-streaming apple http live streaming,m3u8", .description = "HTTP-based media streaming communications protocol", .notes = "HLS can be used with a JavaScript library in browsers that doesn't support it natively as long as they support Media Source Extensions.", .summary = .{ "154 Full", "156 No", "27 Full", "152 No" }, .details = .{ "Version history: 4–141: No; 142–154: Full.", "Version history: 2–156: No.", "Version history: 3.1–5.1: No; 6–27: Full.", "Version history: 12–18: Full; 79–152: No." } },
    .{ .slug = "publickeypinning", .title = "HTTP Public Key Pinning", .search = "HTTP Public Key Pinning publickeypinning pkp,hpkp,security,header", .description = "Declare that a website's HTTPS certificate should only be treated as valid if the public key is contained in a list specified over HTTP to prevent MITM attacks that use valid CA-issued certificates.", .notes = "All browsers have removed support. The header was too complicated to use, and when incorrectly implemented, could completely block websites for longer periods of time. Certificate transparency is widely used and tries to provide the same security by very different means.", .summary = .{ "154 No", "156 No", "27 No", "152 No" }, .details = .{ "Version history: 4–37: No; 38–71: Full; 72–154: No.", "Version history: 2–34: No; 35–71: Full; 72–156: No.", "Version history: 3.1–27: No.", "Version history: 12–152: No." } },
    .{ .slug = "http2", .title = "HTTP/2 protocol", .search = "HTTP/2 protocol http2 https/2", .description = "Networking protocol for low-latency transport of content over the web. Originally started out from the SPDY protocol, now standardized as HTTP version 2.", .notes = "HTTP/2 is only supported over TLS (HTTPS). See also the precursor of HTTP/2, the SPDY protocol, which has been deprecated and removed from most browsers, in favor of HTTP/2.", .summary = .{ "154 Full (#3)", "156 Full (#3)", "27 Full", "152 Full (#3)" }, .details = .{ "Version history: 4–40: No; 41–50: Full; 51–154: Full (#3).\n#3: Only supports HTTP/2 if the server supports protocol negotiation via ALPN.", "Version history: 2–35: No; 36–52: Full; 53–156: Full (#3).\n#3: Only supports HTTP/2 if the server supports protocol negotiation via ALPN.", "Version history: 3.1–8: No; 9–10.1: Partial (#2); 11–27: Full.\n#2: Partial support in Safari refers to being limited to OS X 10.11 El Capitan and newer.", "Version history: 12–18: Full; 79–152: Full (#3).\n#3: Only supports HTTP/2 if the server supports protocol negotiation via ALPN." } },
