    .{ .slug = "maxlength", .title = "maxlength attribute for input and textarea elements", .search = "maxlength attribute for input and textarea elements maxlength maximum,length,input,textarea,too,long,validity,state", .description = "Declares an upper bound on the number of characters the user can input. Normally the UI ignores attempts by the user to type in additional characters beyond this limit.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–154: Full.", "Version history: 2–3.6: Partial (#1, #2, #3); 4–50: Full (#4); 51–156: Full.\n#1: 's' UI does not prevent the user from typing additional characters beyond the maxlength limit.\n#2: Does not support the HTMLTextAreaElement.maxLength DOM property.\n#3: Does not support ValidityState.tooLong. In some cases, this is because .validity is not supported in the first place.\n#4: Does not support ValidityState.tooLong correctly in the (unlikely) case of the value being initially set too long, then changed by the user to a still incorrect state. See Firefox bug and MS Edge bug.", "Version history: 3.1: Unknown; 3.2–4: Partial (#1, #2, #3); 5: Unknown; 5.1–27: Full.\n#1: 's' UI does not prevent the user from typing additional characters beyond the maxlength limit.\n#2: Does not support the HTMLTextAreaElement.maxLength DOM property.\n#3: Does not support ValidityState.tooLong. In some cases, this is because .validity is not supported in the first place.", "Version history: 12–18: Full (#4); 79–152: Full.\n#4: Does not support ValidityState.tooLong correctly in the (unlikely) case of the value being initially set too long, then changed by the user to a still incorrect state. See Firefox bug and MS Edge bug." } },
