    .{ .slug = "css-not-sel-list", .title = "selector list argument of :not()", .search = "selector list argument of :not() css-not-sel-list negation,not,pseudo,selector,selectors,list,multiple,argument,level,4", .description = "Selectors Level 3 only allowed :not() pseudo-class to accept a single simple selector, which the element must not match any of. Thus, :not(a, .b, [c]) or :not(a.b[c]) did not work. Selectors Level 4 allows :not() to accept a list of selectors. Thus, :not(a):not(.b):not([c]) can instead be written as :not(a, .b, [c]) and :not(a.b[c]) works as intended.", .notes = "", .summary = .{ "154 Full", "156 Full", "27 Full", "152 Full" }, .details = .{ "Version history: 4–87: No; 88–154: Full.", "Version history: 2–83: No; 84–156: Full.", "Version history: 3.1–8: No; 9–27: Full.", "Version history: 12–18: No; 79: Unknown; 80–87: No; 88–152: Full." } },
